#!/bin/zsh
# 第二部分 Seedance。用法: seed_part2.sh s5|s6|s10 [--yes]（不加 --yes 只出计划，不花钱）
# 片段里的秒数按「Seedance 会裁掉音频开头约 0.94s」换算：s6 片段 0s ≈ 歌曲 58.22，s10 片段 0s ≈ 歌曲 73.54
cd "${0:A:h}/.."   # 项目根（脚本所在 scripts/ 的上一级）
K=素材/关键帧; A=素材/音频
TAIL="Use @图像1 as the first frame. Lip sync strictly to @音频1: keep the original vocals, lyrics and timing exactly, do not re-sing or change the song."
C=(xk-video --model 2.0-fast --res 480p --ratio 16:9)
case $1 in
# 非唱跳：不传音频、不对口型（54.94–58.28 用，片段 6 秒，剪辑时可以变速）
s5) $C --duration 6 --ref $K/p2_s5_屏幕里.png --out 镜头/shot_p2s5_screen480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, room and character. Limited animation like a 1990s visual novel: mostly held poses with small movements. Locked camera, single shot, no cuts. She is trapped inside the CRT screen. 0–1.5s: she stays pressed against the inside of the glass, breathing softly, the small fog patch on the glass grows and fades with each breath. 1.5s: she knocks on the glass twice with one gloved fist, the picture inside the screen ripples slightly. 2.5–4s: she presses both palms flat on the glass again, tears welling up, looking out at the viewer pleadingly. 4–6s: the scanlines flicker and the picture inside the screen jitters with small digital glitches; she looks up with teary, hopeful eyes. The monitor, the sticky note and the dark room outside the screen stay completely still. Use @图像1 as the first frame.";;
# 唱跳：全身大动作，音频 57.28–66.28（9 秒）
s6) $C --duration 9 --ref $K/p2_s6_楼顶全身.png --audio $A/p2s6_57.28-66.28.mp3 --out 镜头/shot_p2s6_roof480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, costume and character. Full-body shot, the whole figure always in frame from head to boots, energetic 1990s idol dance choreography synced to the beat, singing with lip sync. Locked camera, single shot, no cuts. 0–1.1s: she sings and pumps her raised fist on the beat, bouncing on her knees. 1.1–2.0s: she crouches down low with arms crossed, gathering energy. 2.0s, on the beat drop: she leaps high into the air with arms and legs spread in a star shape, then lands in a wide power stance. 2.8s: she does one full fast spin, skirt and hair flaring out. 3.6s, on \"boom\": she stomps and throws both arms straight up to the sky. 4.1–5.6s: she points up at the sky, following it with her eyes, then big side steps left and right with wide arm swings. 6.0s: she raises both arms to make a big circle over her head. 6.5–9s: hip-sway dance with big arm waves, and at 7.3s she ends pointing straight at the camera with a big grin. $TAIL";;
# 唱跳：Forward MLP, backward, repeat。音频 72.60–78.60（6 秒）
s10) $C --duration 6 --ref $K/p2_s10_跳舞毯全身.png --audio $A/p2s10_72.60-78.60.mp3 --out 镜头/shot_p2s10_ddr480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, costume and character. Full-body shot, the whole figure always in frame from head to boots, energetic 1990s idol dance choreography synced to the beat, singing with lip sync. Locked camera, single shot, no cuts. 0–1.0s, on \"forward\": she hops one big step forward toward the camera, both fists punching forward. 1.0–2.4s: three sharp stomps on the beat, left, right, left, arms pumping. 2.5s, on \"backward\": she hops one big step backward, arms swinging back. 2.9–4.2s, on \"repeat\": a full 360-degree spin with arms stretched out, skirt flaring. 4.2–6s: she lands, does one quick step forward and back again, and freezes in a cute pose. $TAIL";;
esac
